import { Box, Container, Stack, Typography } from "@mui/material";
import masterData from "../../data/masterData.json";
import { getIcon } from "../../utils/iconMap";
import LeadFormCard from "./LeadFormCard";

export default function HeroSection() {
  const { brand, hero } = masterData;

  return (
    <Box
      sx={{
        position: "relative",
        overflow: "hidden",
        background:
          "radial-gradient(ellipse 70% 55% at 58% 45%, #CDE0FF 0%, transparent 60%), linear-gradient(180deg, #F3F7FF 0%, #EEF4FC 40%, #FFFFFF 100%)",
        pt: { xs: 2, md: 2.5 },
        pb: { xs: 4, md: 5 },
      }}
    >
      <Box
        sx={{
          position: "absolute",
          inset: 0,
          opacity: 0.3,
          backgroundImage:
            "radial-gradient(circle, rgba(0,86,210,0.2) 1.1px, transparent 1.1px)",
          backgroundSize: "26px 26px",
          pointerEvents: "none",
        }}
      />

      <Container maxWidth="lg" sx={{ position: "relative", zIndex: 2 }}>
        <Stack direction="row" alignItems="center" spacing={1.1} sx={{ mb: { xs: 2.5, md: 3 } }}>
          <Box component="img" src={brand.logo} alt={brand.name} sx={{ width: 34, height: 34 }} />
          <Typography
            sx={{
              fontWeight: 800,
              fontSize: 14,
              letterSpacing: "0.08em",
              color: "#0B1F3A",
            }}
          >
            {brand.name}
          </Typography>
        </Stack>

        {/* Desktop: text + form, doctor absolute behind */}
        <Box
          sx={{
            position: "relative",
            minHeight: { md: 560 },
          }}
        >
          {/* Doctor — centered absolute on desktop */}
          <Box
            sx={{
              display: { xs: "none", md: "block" },
              position: "absolute",
              left: "48%",
              bottom: -10,
              transform: "translateX(-50%)",
              width: 400,
              height: 580,
              zIndex: 1,
              pointerEvents: "none",
            }}
          >
            <Box
              sx={{
                position: "absolute",
                bottom: 40,
                left: "50%",
                transform: "translateX(-50%)",
                width: 300,
                height: 300,
                borderRadius: "50%",
                background: "radial-gradient(circle, #A8C9FF 0%, transparent 70%)",
                filter: "blur(10px)",
              }}
            />
            <Box
              component="img"
              src={hero.image}
              alt="Doctor"
              sx={{
                position: "relative",
                zIndex: 1,
                width: "100%",
                height: "100%",
                objectFit: "cover",
                objectPosition: "top center",
                maskImage: "linear-gradient(to bottom, #000 72%, transparent 100%)",
                WebkitMaskImage: "linear-gradient(to bottom, #000 72%, transparent 100%)",
              }}
            />
          </Box>

          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: { xs: "1fr", md: "1fr 400px" },
              gap: { xs: 3, md: 4 },
              alignItems: "start",
              position: "relative",
              zIndex: 2,
            }}
          >
            {/* Left copy */}
            <Box sx={{ maxWidth: { md: 460 }, pt: { md: 1 } }}>
              <Typography
                sx={{
                  color: "#0056D2",
                  fontWeight: 700,
                  fontSize: 11,
                  letterSpacing: "0.14em",
                  mb: 1.5,
                }}
              >
                {brand.eyebrow}
              </Typography>

              <Typography
                component="h1"
                sx={{
                  fontWeight: 800,
                  color: "#0B1F3A",
                  fontSize: { xs: "1.7rem", sm: "2.05rem", md: "2.35rem" },
                  lineHeight: 1.18,
                  mb: 1.75,
                  letterSpacing: "-0.02em",
                }}
              >
                {hero.headlineBefore}
                <Box component="span" sx={{ color: "#0056D2" }}>
                  {hero.headlineHighlight}
                </Box>
              </Typography>

              <Typography
                sx={{
                  fontWeight: 700,
                  color: "#0B1F3A",
                  fontSize: { xs: 15, md: 16.5 },
                  mb: 1.25,
                }}
              >
                {hero.subheadline}
              </Typography>

              <Box sx={{ position: "relative", mb: 2.5 }}>
                <Typography
                  sx={{
                    color: "#5A6B80",
                    fontSize: { xs: 13.5, md: 14.5 },
                    lineHeight: 1.7,
                    maxWidth: 380,
                  }}
                >
                  {hero.description}
                </Typography>
                <Typography
                  sx={{
                    display: { xs: "none", lg: "block" },
                    position: "absolute",
                    right: { lg: -20, xl: 20 },
                    top: 0,
                    width: 100,
                    fontFamily: "'Segoe Script', 'Brush Script MT', cursive",
                    fontSize: 12.5,
                    lineHeight: 1.25,
                    color: "#0056D2",
                    fontWeight: 600,
                    textAlign: "right",
                    transform: "rotate(-8deg)",
                    whiteSpace: "pre-line",
                  }}
                >
                  {hero.scriptText}
                </Typography>
              </Box>

              <Box
                sx={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: 1.5,
                  mb: 2.25,
                  maxWidth: 420,
                }}
              >
                {hero.stats.map((stat) => {
                  const Icon = getIcon(stat.icon);
                  return (
                    <Stack key={stat.id} direction="row" spacing={1} alignItems="center">
                      <Box
                        sx={{
                          width: 34,
                          height: 34,
                          borderRadius: "50%",
                          bgcolor: "#E5F0FF",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          flexShrink: 0,
                        }}
                      >
                        <Icon sx={{ color: "#0056D2", fontSize: 18 }} />
                      </Box>
                      <Typography
                        sx={{ fontSize: 12.5, fontWeight: 700, color: "#0B1F3A", lineHeight: 1.25 }}
                      >
                        {stat.value ? (
                          <>
                            <Box component="span" sx={{ color: "#0056D2" }}>
                              {stat.value}
                            </Box>{" "}
                            {stat.label}
                          </>
                        ) : (
                          stat.label
                        )}
                      </Typography>
                    </Stack>
                  );
                })}
              </Box>

              <Stack
                direction="row"
                alignItems="center"
                spacing={1.25}
                sx={{
                  display: "inline-flex",
                  bgcolor: "#fff",
                  border: "1px solid #E0EAF6",
                  borderRadius: "999px",
                  px: 1.5,
                  py: 0.75,
                  boxShadow: "0 4px 14px rgba(0,86,210,0.08)",
                }}
              >
                <Box
                  component="img"
                  src={hero.cpdBadge}
                  alt="CPD"
                  sx={{ width: 36, height: 36 }}
                />
                <Typography sx={{ fontSize: 12, fontWeight: 600, color: "#0B1F3A" }}>
                  {hero.cpdLabel}
                </Typography>
              </Stack>
            </Box>

            {/* Right form */}
            <Box
              sx={{
                display: "flex",
                justifyContent: { xs: "stretch", md: "flex-end" },
                position: "relative",
                zIndex: 3,
              }}
            >
              <LeadFormCard />
            </Box>
          </Box>

          {/* Mobile doctor */}
          <Box
            sx={{
              display: { xs: "flex", md: "none" },
              justifyContent: "center",
              mt: 1,
            }}
          >
            <Box
              component="img"
              src={hero.image}
              alt="Doctor"
              sx={{
                width: "65%",
                maxWidth: 260,
                height: 300,
                objectFit: "cover",
                objectPosition: "top",
                borderRadius: 2,
              }}
            />
          </Box>
        </Box>
      </Container>
    </Box>
  );
}
